    },
    {
      "key_point": "S2.K2",
      "question": "How does Stevens' power law mathematically describe the relationship between a stimulus's actual magnitude and how intensely it is perceived?",
      "answer": "The relationship is represented by the formula P = C * M^x, where M is the magnitude of the original stimulus and P is the resulting perceived magnitude."
    },
    {
      "key_point": "S2.K3",
      "question": "What does the Just Noticeable Difference (JND) represent, and what law is used to capture this concept?",
      "answer": "JND is the minimum change in a stimulus required for subjects to perceive a change in at least 50% of trials, and this concept is captured by Weber's law ($\\Delta M / M = C$)."
    }
  ],
